-- Server-Side Security: PostgreSQL Dynamic Daily Gold Rate & Bill Estimation Functions
-- Date: 2026-08-09

-- 1. Helper function for safe numeric casting in PL/pgSQL
CREATE OR REPLACE FUNCTION public.safe_cast_numeric(p_str TEXT, p_default NUMERIC DEFAULT 0)
RETURNS NUMERIC AS $$
BEGIN
  IF p_str IS NULL OR p_str = '' THEN
    RETURN p_default;
  END IF;
  IF p_str ~ '^d+.d+.d+' THEN
    p_str := regexp_replace(p_str, '^(d+.d+).(d+)', '\1\2');
  END IF;
  RETURN p_str::numeric;
EXCEPTION WHEN OTHERS THEN
  RETURN p_default;
END;
$$ LANGUAGE plpgsql IMMUTABLE;

-- 2. Definitive Server-Side Estimator Function (Created FIRST to satisfy triggers)
CREATE OR REPLACE FUNCTION public.calculate_item_estimate(
  p_net_wt NUMERIC,
  p_wastage NUMERIC,
  p_purity TEXT,
  p_labour_rate NUMERIC,
  p_labour_amt NUMERIC,
  p_stones_json JSONB,
  p_gold_rate_override NUMERIC DEFAULT NULL
)
RETURNS TABLE (
  gold_value NUMERIC(12, 2),
  stone_value NUMERIC(12, 2),
  labour_charge NUMERIC(12, 2),
  sub_total NUMERIC(12, 2),
  gst_amt NUMERIC(12, 2),
  total_estimate NUMERIC(12, 2),
  applied_gold_rate NUMERIC(12, 2)
) AS $$
DECLARE
  v_latest_22k_rate NUMERIC(12, 2);
  v_effective_gold_rate NUMERIC(12, 2);
  v_wastage_pct NUMERIC(10, 3);
  v_gold_val NUMERIC(12, 2);
  v_stone_val NUMERIC(12, 2) := 0;
  v_labour_val NUMERIC(12, 2);
  v_sub NUMERIC(12, 2);
  v_gst NUMERIC(12, 2);
  v_tot NUMERIC(12, 2);
  v_stone RECORD;
BEGIN
  IF p_gold_rate_override IS NOT NULL AND p_gold_rate_override > 0 THEN
    v_latest_22k_rate := p_gold_rate_override;
  ELSE
    SELECT COALESCE(
      (SELECT rate_per_gram_usd FROM public.gold_rates WHERE purity IN ('22K', '22 KT', '22') ORDER BY updated_at DESC LIMIT 1),
      (SELECT rate_per_gram_usd * (22.0/24.0) FROM public.gold_rates WHERE purity IN ('24K', '24 KT', '24') ORDER BY updated_at DESC LIMIT 1),
      14019.00
    ) INTO v_latest_22k_rate;
  END IF;

  IF p_purity ILIKE '%18%' THEN
    v_effective_gold_rate := v_latest_22k_rate * (18.0 / 22.0);
  ELSE
    v_effective_gold_rate := v_latest_22k_rate;
  END IF;

  v_wastage_pct := COALESCE(p_wastage, 25.0);

  v_gold_val := ROUND(COALESCE(p_net_wt, 0) * (1.0 + (v_wastage_pct / 100.0)) * v_effective_gold_rate, 2);

  IF p_stones_json IS NOT NULL AND jsonb_typeof(p_stones_json) = 'array' THEN
    FOR v_stone IN 
      SELECT 
        COALESCE(public.safe_cast_numeric(elem->>'weight'), public.safe_cast_numeric(elem->>'pcs'), 0) AS wt,
        public.safe_cast_numeric(elem->>'rate') AS rt
      FROM jsonb_array_elements(p_stones_json) AS elem
    LOOP
      v_stone_val := v_stone_val + ROUND(v_stone.wt * v_stone.rt, 2);
    END LOOP;
  END IF;

  IF COALESCE(p_labour_amt, 0) > 0 THEN
    v_labour_val := ROUND(p_labour_amt, 2);
  ELSE
    v_labour_val := ROUND(COALESCE(p_net_wt, 0) * COALESCE(p_labour_rate, 550), 2);
  END IF;

  v_sub := v_gold_val + v_stone_val + v_labour_val;
  v_gst := ROUND(v_sub * 0.03, 2);
  v_tot := v_sub + v_gst;

  RETURN QUERY SELECT v_gold_val, v_stone_val, v_labour_val, v_sub, v_gst, v_tot, v_effective_gold_rate;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 3. Server-Side Automated Trigger for public.items
CREATE OR REPLACE FUNCTION public.sync_item_calculated_price()
RETURNS TRIGGER AS $$
DECLARE
  v_est RECORD;
  v_stones_json JSONB;
BEGIN
  BEGIN
    v_stones_json := NEW.stones_in_detail::jsonb;
  EXCEPTION WHEN OTHERS THEN
    v_stones_json := '[]'::jsonb;
  END;

  SELECT * INTO v_est FROM public.calculate_item_estimate(
    NEW.net_wt::numeric,
    NEW.wastage::numeric,
    NEW.purity::text,
    NEW.labour_rate::numeric,
    NEW.labour_amt::numeric,
    COALESCE(v_stones_json, '[]'::jsonb)::jsonb,
    NULL::numeric
  );

  NEW.prc_amount := v_est.total_estimate;
  NEW.cost_price := ROUND(v_est.total_estimate / 83.0, 2);
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 4. Drop existing triggers before updating gold_rates
DROP TRIGGER IF EXISTS trg_sync_item_price ON public.items;
DROP TRIGGER IF EXISTS trg_gold_rate_updated ON public.gold_rates;

CREATE TRIGGER trg_sync_item_price
BEFORE INSERT OR UPDATE ON public.items
FOR EACH ROW EXECUTE FUNCTION public.sync_item_calculated_price();

-- 5. Seed Initial Default 22K/24K Gold Rate in public.gold_rates
ON CONFLICT DO NOTHING;

-- 6. Trigger on public.gold_rates to refresh item prices when daily rate changes
CREATE OR REPLACE FUNCTION public.on_gold_rate_updated()
RETURNS TRIGGER AS $$
BEGIN
  UPDATE public.items SET updated_at = NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE TRIGGER trg_gold_rate_updated
AFTER INSERT OR UPDATE ON public.gold_rates
FOR EACH ROW EXECUTE FUNCTION public.on_gold_rate_updated();

-- 7. Secure View for Detailed Estimates
DROP VIEW IF EXISTS public.v_item_estimates CASCADE;
CREATE OR REPLACE VIEW public.v_item_estimates AS
SELECT 
  i.*,
  est.applied_gold_rate,
  est.gold_value,
  est.stone_value,
  est.labour_charge,
  est.sub_total,
  est.gst_amt,
  est.total_estimate,
  ROUND(est.total_estimate / 83.0, 2) AS calculated_usd_price
FROM public.items i
LEFT JOIN LATERAL public.calculate_item_estimate(
  i.net_wt::numeric,
  i.wastage::numeric,
  i.purity::text,
  i.labour_rate::numeric,
  i.labour_amt::numeric,
  CASE 
    WHEN i.stones_in_detail IS NULL THEN '[]'::jsonb
    WHEN i.stones_in_detail ~ '^s*[' THEN i.stones_in_detail::jsonb
    ELSE '[]'::jsonb
  END::jsonb,
  NULL::numeric
) est ON true;

GRANT EXECUTE ON FUNCTION public.calculate_item_estimate TO authenticated, anon, service_role;

-- 8. Clean up any previous items and drop unique index constraints if present
TRUNCATE TABLE public.items CASCADE;
ALTER TABLE public.items DROP CONSTRAINT IF EXISTS items_barcode_key;
ALTER TABLE public.items DROP CONSTRAINT IF EXISTS items_sku_key;

